/**
 * Base Controller
 *
 * Abstract base class providing common functionality for all controllers.
 * Includes standardized response methods and error handling.
 */
import type { FastifyReply } from 'fastify';
import { Logger, type ILogger } from '../utils/logger.js';

/**
 * Standard API success response
 */
export interface ApiSuccessResponse<T = unknown> {
  isError: false;
  data?: T;
  [key: string]: unknown;
}

/**
 * Standard API error response
 */
export interface ApiErrorResponse {
  isError: true;
  message: string;
}

/**
 * Paginated response wrapper
 */
export interface PaginatedResponse<T> {
  isError: false;
  data: T[];
  pagination: {
    total: number;
    page: number;
    limit: number;
    pages: number;
    hasMore: boolean;
  };
}

/**
 * Base controller class
 *
 * Provides utility methods for sending consistent API responses.
 * All controllers should extend this class.
 */
export abstract class BaseController {
  /**
   * Controller name for logging
   */
  protected readonly controllerName: string;

  /**
   * Logger instance for the controller
   */
  protected readonly logger: ILogger;

  constructor(name: string) {
    this.controllerName = name;
    this.logger = new Logger({ prefix: name });
  }

  /**
   * Send a success response with data
   *
   * @param reply - Fastify reply object
   * @param data - Response data
   * @param messageOrStatus - Optional message string or HTTP status code (default: 200)
   */
  protected sendSuccess<T>(
    reply: FastifyReply,
    data: T,
    messageOrStatus: string | number = 200
  ): void {
    const status = typeof messageOrStatus === 'number' ? messageOrStatus : 200;
    const response = { isError: false as const, ...data };
    void reply.status(status).send(response);
  }

  /**
   * Send a success response without additional data
   *
   * @param reply - Fastify reply object
   * @param status - HTTP status code (default: 200)
   */
  protected sendOk(reply: FastifyReply, status = 200): void {
    void reply.status(status).send({ isError: false });
  }

  /**
   * Send an error response
   *
   * @param reply - Fastify reply object
   * @param message - Error message
   * @param status - HTTP status code (default: 400)
   */
  protected sendError(reply: FastifyReply, message: string, status = 400): void {
    void reply.status(status).send({ isError: true, message });
  }

  /**
   * Send a paginated response
   *
   * @param reply - Fastify reply object
   * @param data - Array of items
   * @param total - Total count (before pagination)
   * @param page - Current page (1-indexed)
   * @param limit - Items per page
   */
  protected sendPaginated<T>(
    reply: FastifyReply,
    data: T[],
    total: number,
    page: number,
    limit: number
  ): void {
    const pages = Math.ceil(total / limit);
    const hasMore = page < pages;

    const response: PaginatedResponse<T> = {
      isError: false,
      data,
      pagination: {
        total,
        page,
        limit,
        pages,
        hasMore,
      },
    };

    void reply.send(response);
  }

  /**
   * Send raw data (for compatibility with existing API)
   *
   * @param reply - Fastify reply object
   * @param data - Raw data to send
   * @param status - HTTP status code (default: 200)
   */
  protected sendRaw(reply: FastifyReply, data: unknown, status = 200): void {
    void reply.status(status).send(data);
  }
}

/**
 * External Videos Controller
 *
 * Handles serving video content (thumbnails, previews, posters, adaptive streams, progressive downloads).
 */
import type { FastifyRequest, FastifyReply } from 'fastify';
import fs from 'node:fs';
import path from 'node:path';
import { BaseController } from './base.js';
import type { VideosRepository } from '../database/repositories/videos.js';
import { getConfig } from '../config/index.js';
import {
  isVideoIdValid,
  isAdaptiveFormatValid,
  isProgressiveFormatValid,
  isResolutionValid,
  isManifestNameValid,
  isSegmentNameValid,
  isManifestTypeValid,
  isProgressiveFilenameValid,
} from '../utils/index.js';

/**
 * Route params for video images
 */
interface VideoIdParams {
  videoId: string;
}

/**
 * Route params for adaptive manifests
 */
interface AdaptiveManifestParams {
  videoId: string;
  format: string;
  type: string;
  manifestName: string;
}

/**
 * Route params for adaptive segments
 */
interface AdaptiveSegmentParams {
  videoId: string;
  format: string;
  resolution: string;
  segmentName: string;
}

/**
 * Route params for progressive files
 */
interface ProgressiveParams {
  videoId: string;
  format: string;
  progressiveFilename: string;
}

/**
 * ExternalVideosController class
 *
 * Handles:
 * - Get external videos base URL
 * - Serve video thumbnail images
 * - Serve video preview images
 * - Serve video poster images
 * - Serve HLS/DASH manifests
 * - Serve HLS/DASH segments
 * - Serve progressive video files (with range support)
 */
export class ExternalVideosController extends BaseController {
  // Bandwidth tracking state
  private segmentBandwidthCounter = 0;
  private segmentBandwidthTimer: ReturnType<typeof setTimeout> | null = null;
  private progressiveBandwidthCounter = 0;
  private progressiveBandwidthTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(private readonly videoRepository: VideosRepository) {
    super('ExternalVideosController');
  }

  /**
   * GET /external/videos/baseUrl
   *
   * Get external videos base URL
   */
  getBaseUrl = async (_request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const config = getConfig();
      const externalVideosBaseUrl = config.getExternalVideosBaseUrl();

      this.sendSuccess(reply, { externalVideosBaseUrl });
    } catch (error) {
      this.logger.error('Get base URL failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * GET /external/videos/:videoId/images/thumbnail.jpg
   *
   * Serve video thumbnail image
   */
  getThumbnail = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        void reply.status(404).send('thumbnail not found');
        return;
      }

      const config = getConfig();
      const thumbnailPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'images',
        'thumbnail.jpg'
      );

      if (!fs.existsSync(thumbnailPath)) {
        void reply.status(404).send('thumbnail not found');
        return;
      }

      const fileStream = fs.createReadStream(thumbnailPath);
      void reply.header('Content-Type', 'image/jpeg').send(fileStream);
    } catch (error) {
      this.logger.error('Get thumbnail failed', error instanceof Error ? error : null);
      void reply.status(404).send('thumbnail not found');
    }
  };

  /**
   * GET /external/videos/:videoId/images/preview.jpg
   *
   * Serve video preview image
   */
  getPreview = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        void reply.status(404).send('preview not found');
        return;
      }

      const config = getConfig();
      const previewPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'images',
        'preview.jpg'
      );

      if (!fs.existsSync(previewPath)) {
        void reply.status(404).send('preview not found');
        return;
      }

      const fileStream = fs.createReadStream(previewPath);
      void reply.header('Content-Type', 'image/jpeg').send(fileStream);
    } catch (error) {
      this.logger.error('Get preview failed', error instanceof Error ? error : null);
      void reply.status(404).send('preview not found');
    }
  };

  /**
   * GET /external/videos/:videoId/images/poster.jpg
   *
   * Serve video poster image
   */
  getPoster = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        void reply.status(404).send('poster not found');
        return;
      }

      const config = getConfig();
      const posterPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'images',
        'poster.jpg'
      );

      if (!fs.existsSync(posterPath)) {
        void reply.status(404).send('poster not found');
        return;
      }

      const fileStream = fs.createReadStream(posterPath);
      void reply.header('Content-Type', 'image/jpeg').send(fileStream);
    } catch (error) {
      this.logger.error('Get poster failed', error instanceof Error ? error : null);
      void reply.status(404).send('poster not found');
    }
  };

  /**
   * GET /external/videos/:videoId/adaptive/:format/:type/manifests/:manifestName
   *
   * Serve HLS/DASH manifest files
   */
  getAdaptiveManifest = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId, format, type, manifestName } = request.params as AdaptiveManifestParams;

      if (
        !isVideoIdValid(videoId, false) ||
        !isAdaptiveFormatValid(format) ||
        !isManifestTypeValid(type) ||
        !isManifestNameValid(manifestName)
      ) {
        void reply.status(404).send('video not found');
        return;
      }

      const config = getConfig();
      const manifestPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'adaptive',
        format,
        manifestName
      );

      if (!fs.existsSync(manifestPath)) {
        void reply.status(404).send('video not found');
        return;
      }

      const fileStream = fs.createReadStream(manifestPath);
      void reply.header('Content-Type', 'application/vnd.apple.mpegurl').send(fileStream);
    } catch (error) {
      this.logger.error('Get adaptive manifest failed', error instanceof Error ? error : null);
      void reply.status(404).send('video not found');
    }
  };

  /**
   * GET /external/videos/:videoId/adaptive/:format/:resolution/segments/:segmentName
   *
   * Serve HLS/DASH segment files with bandwidth tracking
   */
  getAdaptiveSegment = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId, format, resolution, segmentName } = request.params as AdaptiveSegmentParams;

      if (
        !isVideoIdValid(videoId, false) ||
        !isAdaptiveFormatValid(format) ||
        !isResolutionValid(resolution) ||
        !isSegmentNameValid(segmentName)
      ) {
        void reply.status(404).send('video not found');
        return;
      }

      const config = getConfig();
      const segmentPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'adaptive',
        format,
        resolution,
        segmentName
      );

      if (!fs.existsSync(segmentPath)) {
        void reply.status(404).send('video not found');
        return;
      }

      // Track bandwidth asynchronously
      this.trackSegmentBandwidth(segmentPath, videoId);

      const fileStream = fs.createReadStream(segmentPath);
      void reply.header('Content-Type', 'video/mp2t').send(fileStream);
    } catch (error) {
      this.logger.error('Get adaptive segment failed', error instanceof Error ? error : null);
      void reply.status(404).send('video not found');
    }
  };

  /**
   * GET /external/videos/:videoId/progressive/:format/:progressiveFilename
   *
   * Serve progressive video files with range request support
   */
  getProgressive = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId, format, progressiveFilename } = request.params as ProgressiveParams;

      if (
        !isVideoIdValid(videoId, false) ||
        !isProgressiveFormatValid(format) ||
        !isProgressiveFilenameValid(progressiveFilename)
      ) {
        void reply.status(404).send('video not found');
        return;
      }

      const config = getConfig();
      const filePath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'progressive',
        format,
        progressiveFilename
      );

      if (!fs.existsSync(filePath)) {
        void reply.status(404).send('video not found');
        return;
      }

      const stat = fs.statSync(filePath);
      const fileSize = stat.size;
      const range = request.headers.range;

      if (typeof range === 'string' && range.length > 0) {
        // Handle range request
        const parts = range.replace(/bytes=/, '').split('-');
        const startPart = parts[0];
        const endPart = parts[1];
        const start =
          startPart !== undefined && startPart !== '' ? Number.parseInt(startPart, 10) : 0;
        const end =
          endPart !== undefined && endPart !== '' ? Number.parseInt(endPart, 10) : fileSize - 1;
        const chunkSize = end - start + 1;

        // Track bandwidth
        this.trackProgressiveBandwidth(chunkSize, videoId);

        const fileStream = fs.createReadStream(filePath, { start, end });

        void reply
          .status(206)
          .header('Content-Range', `bytes ${start}-${end}/${fileSize}`)
          .header('Accept-Ranges', 'bytes')
          .header('Content-Length', chunkSize)
          .header('Content-Type', `video/${format}`)
          .send(fileStream);
      } else {
        // Full file request
        const fileStream = fs.createReadStream(filePath);

        void reply
          .header('Content-Length', fileSize)
          .header('Content-Type', `video/${format}`)
          .send(fileStream);
      }
    } catch (error) {
      this.logger.error('Get progressive video failed', error instanceof Error ? error : null);
      void reply.status(404).send('video not found');
    }
  };

  /**
   * Track bandwidth for adaptive segments (debounced)
   */
  private trackSegmentBandwidth(segmentPath: string, videoId: string): void {
    fs.stat(segmentPath, (error, stats) => {
      if (error) {
        return;
      }

      this.segmentBandwidthCounter += stats.size;

      if (this.segmentBandwidthTimer) {
        clearTimeout(this.segmentBandwidthTimer);
      }

      this.segmentBandwidthTimer = setTimeout(() => {
        const bandwidth = this.segmentBandwidthCounter;
        this.segmentBandwidthCounter = 0;

        // Update bandwidth in database
        void this.videoRepository.updateBandwidth(videoId, bandwidth);
      }, 100);
    });
  }

  /**
   * Track bandwidth for progressive downloads (debounced)
   */
  private trackProgressiveBandwidth(chunkSize: number, videoId: string): void {
    this.progressiveBandwidthCounter += chunkSize;

    if (this.progressiveBandwidthTimer) {
      clearTimeout(this.progressiveBandwidthTimer);
    }

    this.progressiveBandwidthTimer = setTimeout(() => {
      const bandwidth = this.progressiveBandwidthCounter;
      this.progressiveBandwidthCounter = 0;

      // Update bandwidth in database
      void this.videoRepository.updateBandwidth(videoId, bandwidth);
    }, 100);
  }
}

/**
 * Node Controller
 *
 * Handles the main node page and related endpoints.
 */
import type { FastifyRequest, FastifyReply } from 'fastify';

import { BaseController } from './base.js';
import type { VideosRepository } from '../database/repositories/videos.js';
import type { CommentsRepository } from '../database/repositories/comments.js';
import type { ReportsVideosRepository } from '../database/repositories/reports-videos.js';
import type { ReportsCommentsRepository } from '../database/repositories/reports-comments.js';
import type { LinksRepository } from '../database/repositories/links.js';
import type { MonetizationRepository } from '../database/repositories/monetization.js';
import type { DrizzleVideo } from '../database/schema/index.js';
import { getConfig } from '../config/index.js';
import { isSearchTermValid, isSortTermValid, isTagTermValid } from '../utils/index.js';

/**
 * Fastify reply with view engine support
 */
interface FastifyReplyWithView extends FastifyReply {
  view?: (template: string, data: Record<string, unknown>) => FastifyReply;
}

/**
 * Query parameters for node page
 */
export interface NodeQuery {
  searchTerm?: string;
  sortTerm?: string;
  tagTerm?: string;
}

/**
 * Request body for content checked
 */
export interface ContentCheckedBody {
  contentType: 'comments' | 'videoReports' | 'commentReports';
}

/**
 * NodeController class
 *
 * Handles:
 * - Main node page rendering
 * - Video search
 * - New content counts
 * - Content check marking
 */
export class NodeController extends BaseController {
  constructor(
    private readonly videoRepository: VideosRepository,
    private readonly commentRepository: CommentsRepository,
    private readonly videoReportRepository: ReportsVideosRepository,
    private readonly commentReportRepository: ReportsCommentsRepository,
    private readonly linkRepository: LinksRepository,
    private readonly monetizationRepository: MonetizationRepository
  ) {
    super('NodeController');
  }

  /**
   * GET /node
   *
   * Render the main node page
   */
  getNodePage = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const queryParams = request.query as NodeQuery;

      // Validate and sanitize query parameters
      const searchTerm = isSearchTermValid(queryParams.searchTerm ?? '')
        ? (queryParams.searchTerm ?? '')
        : '';
      const sortTerm = isSortTermValid(queryParams.sortTerm ?? '')
        ? (queryParams.sortTerm ?? 'latest')
        : 'latest';
      const tagTerm = isTagTermValid(queryParams.tagTerm ?? '', true)
        ? (queryParams.tagTerm ?? '')
        : '';

      const config = getConfig();
      const nodeSettings = config.nodeSettings;

      // Get node information
      const videoCount = await this.videoRepository.count({ isPublished: true });
      const informationData = {
        isError: false,
        information: {
          nodeVideoCount: videoCount,
          nodeId: String(nodeSettings.nodeId ?? ''),
          nodeName: String(nodeSettings.nodeName ?? ''),
          nodeAbout: String(nodeSettings.nodeAbout ?? ''),
          publicNodeProtocol: String(nodeSettings.publicNodeProtocol ?? ''),
          publicNodeAddress: String(nodeSettings.publicNodeAddress ?? ''),
          publicNodePort: String(nodeSettings.publicNodePort ?? ''),
          cloudflareTurnstileSiteKey: String(nodeSettings.cloudflareTurnstileSiteKey ?? ''),
        },
      };

      // Get links
      const links = await this.linkRepository.findAll();
      const linksData = { isError: false, links };

      // Get crypto wallet addresses
      const walletAddresses = await this.monetizationRepository.findAll();
      const cryptoWalletAddressesData = { isError: false, cryptoWalletAddresses: walletAddresses };

      // Get all unique tags
      const allVideos = await this.videoRepository.findAll({
        isPublished: true,
      });

      const tagsSet = new Set<string>();
      for (const video of allVideos) {
        const videoTags = video.tags?.split(',') ?? [];
        for (const tag of videoTags) {
          if (tag.trim()) {
            tagsSet.add(tag.trim());
          }
        }
      }
      const tagsData = { isError: false, tags: Array.from(tagsSet) };

      // Get search results
      const searchResultsData = await this.performSearch(searchTerm, sortTerm, tagTerm);

      const externalVideosBaseUrl = config.getExternalVideosBaseUrl();
      const externalResourcesBaseUrl = config.getExternalResourcesBaseUrl();

      // Render the node page
      const replyWithView = reply as FastifyReplyWithView;
      if (replyWithView.view) {
        void replyWithView.view('node', {
          informationData,
          linksData,
          cryptoWalletAddressesData,
          tagsData,
          searchResultsData,
          externalVideosBaseUrl,
          externalResourcesBaseUrl,
        });
      } else {
        // Fallback to JSON response if view engine not available
        void reply.send({
          informationData,
          linksData,
          cryptoWalletAddressesData,
          tagsData,
          searchResultsData,
          externalVideosBaseUrl,
          externalResourcesBaseUrl,
        });
      }
    } catch (error) {
      this.logger.error('Node page rendering failed', error instanceof Error ? error : null);
      void reply.status(500).send('node page rendering error');
    }
  };

  /**
   * GET /node/search
   *
   * Search videos
   */
  search = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const queryParams = request.query as NodeQuery;

      // Validate parameters
      const searchTerm = isSearchTermValid(queryParams.searchTerm ?? '')
        ? (queryParams.searchTerm ?? '')
        : '';
      const sortTerm = isSortTermValid(queryParams.sortTerm ?? '')
        ? (queryParams.sortTerm ?? 'latest')
        : 'latest';
      const tagTerm = isTagTermValid(queryParams.tagTerm ?? '', true)
        ? (queryParams.tagTerm ?? '')
        : '';

      const data = await this.performSearch(searchTerm, sortTerm, tagTerm);
      this.sendSuccess(reply, { searchResults: data.searchResults });
    } catch (error) {
      this.logger.error('Search failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * GET /node/newContentCounts
   *
   * Get counts of new content since last check
   */
  getNewContentCounts = async (_request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const config = getConfig();
      const lastCheckedContentTracker = config.lastCheckedContentTracker;

      const lastCheckedCommentsTimestamp = lastCheckedContentTracker.lastCheckedCommentsTimestamp;
      const lastCheckedVideoReportsTimestamp =
        lastCheckedContentTracker.lastCheckedVideoReportsTimestamp;
      const lastCheckedCommentReportsTimestamp =
        lastCheckedContentTracker.lastCheckedCommentReportsTimestamp;

      // Count new content since last check
      const newCommentsCount = await this.commentRepository.countNewerThan(
        lastCheckedCommentsTimestamp
      );
      const newVideoReportsCount = await this.videoReportRepository.countNewerThan(
        lastCheckedVideoReportsTimestamp
      );
      const newCommentReportsCount = await this.commentReportRepository.countNewerThan(
        lastCheckedCommentReportsTimestamp
      );

      this.sendSuccess(reply, {
        newContentCounts: {
          newCommentsCount,
          newVideoReportsCount,
          newCommentReportsCount,
        },
      });
    } catch (error) {
      this.logger.error('Get new content counts failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * POST /node/contentChecked
   *
   * Mark content type as checked
   */
  contentChecked = (request: FastifyRequest, reply: FastifyReply): void => {
    try {
      const { contentType } = request.body as ContentCheckedBody;
      const config = getConfig();

      const timestamp = Date.now();

      if (contentType === 'comments') {
        config.updateLastCheckedContentTracker({ lastCheckedCommentsTimestamp: timestamp });
      } else if (contentType === 'videoReports') {
        config.updateLastCheckedContentTracker({ lastCheckedVideoReportsTimestamp: timestamp });
      } else if (contentType === 'commentReports') {
        config.updateLastCheckedContentTracker({ lastCheckedCommentReportsTimestamp: timestamp });
      }

      this.sendOk(reply);
    } catch (error) {
      this.logger.error('Content checked failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * Perform video search with sorting and tag filtering
   */
  private async performSearch(
    searchTerm: string,
    sortTerm: string,
    tagTerm: string
  ): Promise<{ isError: false; searchResults: DrizzleVideo[] }> {
    const videos = await this.fetchAndMergeVideos(searchTerm);
    const sortedVideos = this.sortVideos(videos, sortTerm);
    const searchResults = this.filterByTag(sortedVideos, tagTerm);

    return { isError: false, searchResults };
  }

  /**
   * Fetch published and live videos, merge and deduplicate
   */
  private async fetchAndMergeVideos(searchTerm: string): Promise<DrizzleVideo[]> {
    const queryOptions: { isPublished: boolean; search?: string } = {
      isPublished: true,
    };

    if (searchTerm.length > 0) {
      queryOptions.search = searchTerm;
    }

    const videos = await this.videoRepository.findAll(queryOptions);
    const liveVideos = await this.videoRepository.findStreaming();

    const videoMap = new Map<string, DrizzleVideo>();
    for (const video of videos) {
      videoMap.set(video.videoId, video);
    }
    for (const video of liveVideos) {
      if (!videoMap.has(video.videoId)) {
        videoMap.set(video.videoId, video);
      }
    }

    return Array.from(videoMap.values());
  }

  /**
   * Sort videos by the given sort term
   */
  private sortVideos(videos: DrizzleVideo[], sortTerm: string): DrizzleVideo[] {
    const sorted = [...videos];

    if (sortTerm === 'latest') {
      sorted.sort((a, b) => b.creationTimestamp - a.creationTimestamp);
    } else if (sortTerm === 'popular') {
      sorted.sort((a, b) => b.views - a.views);
    } else if (sortTerm === 'oldest') {
      sorted.sort((a, b) => a.creationTimestamp - b.creationTimestamp);
    }

    return sorted;
  }

  /**
   * Filter videos by tag with optional tag limit
   */
  private filterByTag(videos: DrizzleVideo[], tagTerm: string): DrizzleVideo[] {
    if (tagTerm.length > 0) {
      return this.filterBySpecificTag(videos, tagTerm);
    }
    return this.filterWithTagLimit(videos);
  }

  /**
   * Filter videos that have a specific tag
   */
  private filterBySpecificTag(videos: DrizzleVideo[], tagTerm: string): DrizzleVideo[] {
    const results: DrizzleVideo[] = [];

    for (const video of videos) {
      const tagsArray = video.tags?.split(',').map((t: string) => t.trim()) ?? [];
      if (tagsArray.includes(tagTerm) && !results.includes(video)) {
        results.push(video);
      }
    }

    return results;
  }

  /**
   * Filter videos with a limit per tag
   */
  private filterWithTagLimit(videos: DrizzleVideo[]): DrizzleVideo[] {
    const tagLimit = 4;
    const tagLimitCounter: Record<string, number> = {};
    const results: DrizzleVideo[] = [];

    for (const video of videos) {
      if (this.shouldAddVideoByTagLimit(video, tagLimitCounter, tagLimit)) {
        results.push(video);
      }
    }

    return results;
  }

  /**
   * Check if video should be added based on tag limit
   */
  private shouldAddVideoByTagLimit(
    video: DrizzleVideo,
    tagLimitCounter: Record<string, number>,
    tagLimit: number
  ): boolean {
    const tagsArray = video.tags?.split(',') ?? [];

    for (const tag of tagsArray) {
      const trimmedTag = tag.trim();
      if (trimmedTag === '') {
        continue;
      }

      if (!(trimmedTag in tagLimitCounter)) {
        tagLimitCounter[trimmedTag] = 0;
      }

      const currentCount = tagLimitCounter[trimmedTag] ?? 0;
      if (currentCount < tagLimit) {
        tagLimitCounter[trimmedTag] = currentCount + 1;
        return true;
      }
    }

    return false;
  }
}

/**
 * Status Controller
 *
 * Handles status and health check endpoints.
 */
import type { FastifyRequest, FastifyReply } from 'fastify';
import { BaseController } from './base.js';
import { getConfig } from '../config/index.js';
import type { Container } from '../core/container.js';

/**
 * Status information response
 */
interface StatusInformation {
  nodeVideoCount: number;
  nodeId: string;
  nodeName: string;
  nodeAbout: string;
  publicNodeProtocol: string;
  publicNodeAddress: string;
  publicNodePort: string;
  cloudflareTurnstileSiteKey: string;
}

interface HealthCheck {
  status: 'ok' | 'error';
  message?: string;
}

/**
 * StatusController class
 *
 * Handles:
 * - Node information endpoint
 * - Heartbeat endpoint
 * - Health checks
 */
export class StatusController extends BaseController {
  private readonly container: Container;

  constructor(container: Container) {
    super('StatusController');
    this.container = container;
  }

  /**
   * GET /status/information
   *
   * Returns node information including video count and public settings
   */
  information = async (_request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const config = getConfig();
    const nodeSettings = config.nodeSettings;

    // Get video count from repository
    const videoRepository = this.container.resolve('videoRepository');
    const videoCount = await videoRepository.count({
      isPublished: true,
    });

    const information: StatusInformation = {
      nodeVideoCount: videoCount,
      nodeId: String(nodeSettings.nodeId ?? ''),
      nodeName: String(nodeSettings.nodeName ?? ''),
      nodeAbout: String(nodeSettings.nodeAbout ?? ''),
      publicNodeProtocol: String(nodeSettings.publicNodeProtocol ?? ''),
      publicNodeAddress: String(nodeSettings.publicNodeAddress ?? ''),
      publicNodePort: String(nodeSettings.publicNodePort ?? ''),
      cloudflareTurnstileSiteKey: String(nodeSettings.cloudflareTurnstileSiteKey ?? ''),
    };

    this.sendSuccess(reply, { information });
  };

  /**
   * GET /status/heartbeat
   *
   * Returns current timestamp for health checks
   */
  heartbeat = (_request: FastifyRequest, reply: FastifyReply): void => {
    this.sendSuccess(reply, { timestamp: Date.now() });
  };

  /**
   * GET /health
   *
   * Basic liveness check
   */
  health = (_request: FastifyRequest, reply: FastifyReply): void => {
    void reply.send({ status: 'ok', timestamp: Date.now() });
  };

  /**
   * GET /health/ready
   *
   * Detailed readiness check including database connectivity
   */
  healthReady = async (_request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    let databaseCheck: HealthCheck = { status: 'ok' };
    let configurationCheck: HealthCheck = { status: 'ok' };

    // Check database connectivity
    try {
      const videoRepository = this.container.resolve('videoRepository');
      await videoRepository.count({});
    } catch (error) {
      databaseCheck = {
        status: 'error',
        message: (error as Error).message,
      };
    }

    // Check configuration
    try {
      const config = getConfig();
      const nodeId = config.nodeSettings.nodeId;
      if (nodeId === undefined || nodeId === '') {
        configurationCheck = {
          status: 'error',
          message: 'Node not configured',
        };
      }
    } catch (error) {
      configurationCheck = {
        status: 'error',
        message: (error as Error).message,
      };
    }

    const isHealthy = databaseCheck.status === 'ok' && configurationCheck.status === 'ok';
    const httpStatus = isHealthy ? 200 : 503;

    void reply.status(httpStatus).send({
      status: isHealthy ? 'ok' : 'degraded',
      timestamp: Date.now(),
      checks: {
        database: databaseCheck,
        configuration: configurationCheck,
      },
    });
  };
}

/**
 * Streams Controller
 *
 * Handles live streaming endpoints.
 */
import fs from 'node:fs';
import path from 'node:path';
import type { FastifyRequest, FastifyReply } from 'fastify';

import { BaseController } from './base.js';
import type { VideosRepository } from '../database/repositories/videos.js';
import type { LiveChatMessageRepository } from '../database/repositories/live-chat-messages.js';
import type { StreamService } from '../services/stream.js';
import { getConfig } from '../config/index.js';
import {
  isTitleValid,
  isDescriptionValid,
  isTagsValid,
  isPortValid,
  isVideoIdValid,
  isAdaptiveFormatValid,
  isResolutionValid,
  isSegmentNameValid,
  isBooleanValid,
  isNetworkAddressValid,
  isChatHistoryLimitValid,
} from '../utils/index.js';

/**
 * Request body for starting a stream
 */
export interface StartStreamBody {
  title: string;
  description: string;
  tags: string;
  rtmpPort: string;
  uuid: string;
  isRecordingStreamRemotely: boolean;
  isRecordingStreamLocally: boolean;
  networkAddress: string;
  resolution: string;
  videoId?: string;
}

/**
 * Request params with videoId
 */
export interface VideoIdParams {
  videoId: string;
}

/**
 * Request params for segment removal
 */
export interface SegmentRemoveParams {
  videoId: string;
  format: string;
  resolution: string;
}

/**
 * Request body for segment removal
 */
export interface SegmentRemoveBody {
  segmentName: string;
}

/**
 * Request body for chat settings
 */
export interface ChatSettingsBody {
  isChatHistoryEnabled: boolean;
  chatHistoryLimit: number;
}

/**
 * StreamsController class
 *
 * Handles:
 * - Starting streams
 * - Stopping streams
 * - Stream segment management
 * - Stream bandwidth
 * - Chat settings and history
 */
export class StreamsController extends BaseController {
  constructor(
    private readonly videoRepository: VideosRepository,
    private readonly liveChatMessageRepository: LiveChatMessageRepository,
    private readonly streamService: StreamService
  ) {
    super('StreamsController');
  }

  /**
   * POST /streams/start
   *
   * Start a new stream or resume an existing one
   */
  startStream = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const {
        title,
        description,
        tags,
        rtmpPort,
        uuid,
        isRecordingStreamRemotely,
        isRecordingStreamLocally,
        networkAddress,
        resolution,
        videoId = '',
      } = request.body as StartStreamBody;

      // Validate all parameters
      if (!isTitleValid(title)) {
        this.sendError(reply, 'title is not valid');
        return;
      }
      if (!isDescriptionValid(description)) {
        this.sendError(reply, 'description is not valid');
        return;
      }
      if (!isTagsValid(tags)) {
        this.sendError(reply, 'tags are not valid');
        return;
      }
      if (!isPortValid(rtmpPort)) {
        this.sendError(reply, 'rtmp port not valid');
        return;
      }
      if (uuid !== 'moartube') {
        this.sendError(reply, 'uuid not valid');
        return;
      }
      if (!isBooleanValid(isRecordingStreamRemotely)) {
        this.sendError(reply, 'isRecordingStreamRemotely not valid');
        return;
      }
      if (!isBooleanValid(isRecordingStreamLocally)) {
        this.sendError(reply, 'isRecordingStreamLocally not valid');
        return;
      }
      if (!isNetworkAddressValid(networkAddress)) {
        this.sendError(reply, 'networkAddress not valid');
        return;
      }
      if (!isResolutionValid(resolution)) {
        this.sendError(reply, 'resolution not valid');
        return;
      }
      if (!isVideoIdValid(videoId, true)) {
        this.sendError(reply, 'videoId not valid');
        return;
      }

      const options: {
        title: string;
        description: string;
        tags: string;
        rtmpPort: number;
        isRecordingStreamRemotely: boolean;
        isRecordingStreamLocally: boolean;
        networkAddress: string;
        resolution: string;
        existingVideoId?: string;
      } = {
        title,
        description,
        tags,
        rtmpPort: Number.parseInt(rtmpPort, 10),
        isRecordingStreamRemotely,
        isRecordingStreamLocally,
        networkAddress,
        resolution,
      };

      if (videoId.length > 0) {
        options.existingVideoId = videoId;
      }

      const result = await this.streamService.startNewStream(options);

      this.sendSuccess(reply, { videoId: result.videoId });
    } catch (error) {
      this.logger.error('Start stream failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * POST /streams/:videoId/stop
   *
   * Stop a stream
   */
  stopStream = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        this.sendError(reply, 'video id is not valid');
        return;
      }

      await this.streamService.stopStream(videoId);

      this.sendOk(reply);
    } catch (error) {
      this.logger.error('Stop stream failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * POST /streams/:videoId/adaptive/:format/:resolution/segments/remove
   *
   * Remove a segment file
   */
  removeSegment = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId, format, resolution } = request.params as SegmentRemoveParams;
      const { segmentName } = request.body as SegmentRemoveBody;

      if (
        !isVideoIdValid(videoId, false) ||
        !isAdaptiveFormatValid(format) ||
        !isResolutionValid(resolution) ||
        !isSegmentNameValid(segmentName)
      ) {
        this.sendError(reply, 'invalid parameters');
        return;
      }

      // Delete the segment file directly
      const config = getConfig();
      const segmentPath = path.join(
        config.paths.videosDirectoryPath,
        videoId,
        'adaptive',
        format,
        resolution,
        segmentName
      );

      try {
        if (fs.existsSync(segmentPath)) {
          fs.unlinkSync(segmentPath);
        }
      } catch {
        // Ignore file deletion errors
      }

      this.sendOk(reply);
    } catch (error) {
      this.logger.error('Remove segment failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * GET /streams/:videoId/bandwidth
   *
   * Get stream bandwidth
   */
  getBandwidth = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        this.sendError(reply, 'invalid parameters');
        return;
      }

      const video = await this.videoRepository.findById(videoId);

      if (video === null) {
        this.sendError(reply, 'that video does not exist');
        return;
      }

      this.sendSuccess(reply, { bandwidth: video.bandwidth });
    } catch (error) {
      this.logger.error('Get bandwidth failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * POST /streams/:videoId/chat/settings
   *
   * Update chat settings for a stream
   */
  updateChatSettings = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;
      const { isChatHistoryEnabled, chatHistoryLimit } = request.body as ChatSettingsBody;

      if (
        !isVideoIdValid(videoId, false) ||
        !isBooleanValid(isChatHistoryEnabled) ||
        !isChatHistoryLimitValid(chatHistoryLimit)
      ) {
        this.sendError(reply, 'invalid parameters');
        return;
      }

      const video = await this.videoRepository.findById(videoId);

      if (video === null) {
        this.sendError(reply, 'that video does not exist');
        return;
      }

      // Update meta with chat settings
      let meta: Record<string, unknown> = {};
      if (video.meta !== undefined && video.meta !== null && video.meta !== '') {
        try {
          meta = JSON.parse(String(video.meta)) as Record<string, unknown>;
        } catch {
          // Invalid JSON
        }
      }

      const chatSettings = (meta['chatSettings'] as Record<string, unknown>) ?? {};
      chatSettings['isChatHistoryEnabled'] = isChatHistoryEnabled;
      chatSettings['chatHistoryLimit'] = chatHistoryLimit;
      meta['chatSettings'] = chatSettings;

      await this.videoRepository.update(videoId, { meta: JSON.stringify(meta) });

      // Clean up chat history if disabled or limited
      if (!isChatHistoryEnabled) {
        await this.liveChatMessageRepository.deleteByVideoId(videoId);
      } else if (chatHistoryLimit > 0) {
        await this.liveChatMessageRepository.pruneOldMessages(videoId, chatHistoryLimit);
      }

      this.sendOk(reply);
    } catch (error) {
      this.logger.error('Update chat settings failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };

  /**
   * GET /streams/:videoId/chat/history
   *
   * Get chat history for a stream
   */
  getChatHistory = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      if (!isVideoIdValid(videoId, false)) {
        this.sendError(reply, 'invalid parameters');
        return;
      }

      const chatHistory = await this.liveChatMessageRepository.findByVideoId(videoId);

      this.sendSuccess(reply, { chatHistory });
    } catch (error) {
      this.logger.error('Get chat history failed', error instanceof Error ? error : null);
      this.sendError(reply, 'error communicating with the MoarTube node');
    }
  };
}

/**
 * Watch Embed Controller
 *
 * Handles embedded video and chat page rendering.
 */
import type { FastifyRequest, FastifyReply } from 'fastify';
import { BaseController } from './base.js';
import type { VideosRepository } from '../database/repositories/videos.js';
import type { LinksRepository } from '../database/repositories/links.js';
import type { MonetizationRepository } from '../database/repositories/monetization.js';
import { getConfig } from '../config/index.js';

/**
 * Route params for video/chat endpoints
 */
interface VideoIdParams {
  videoId: string;
}

/**
 * Query params for video embed
 */
interface VideoEmbedQuery {
  autostart?: string;
}

/**
 * Extended FastifyReply with view method
 * View engine will be registered in app setup
 */
interface FastifyReplyWithView extends FastifyReply {
  view(template: string, data: Record<string, unknown>): Promise<FastifyReply>;
}

/**
 * WatchEmbedController class
 *
 * Handles:
 * - Render embedded video player page
 * - Render embedded chat page
 */
export class WatchEmbedController extends BaseController {
  constructor(
    private readonly videoRepository: VideosRepository,
    private readonly linkRepository: LinksRepository,
    private readonly monetizationRepository: MonetizationRepository
  ) {
    super('WatchEmbedController');
  }

  /**
   * GET /watch/embed/video/:videoId
   *
   * Render embedded video player page
   */
  getEmbedVideo = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;
      const { autostart } = request.query as VideoEmbedQuery;

      const video = await this.videoRepository.findById(videoId);

      if (!video) {
        this.sendError(reply, 'video not found', 404);
        return;
      }

      const config = getConfig();
      const nodeSettings = config.nodeSettings;

      // Build video data for template
      const videoData = {
        videoId: video.videoId,
        title: video.title,
        description: video.description,
        tags: video.tags,
        lengthSeconds: video.lengthSeconds,
        lengthTimestamp: video.lengthTimestamp,
        views: video.views,
        likes: video.likes,
        dislikes: video.dislikes,
        isPublished: video.isPublished,
        isLive: video.isLive,
        isStreaming: video.isStreaming,
        outputs: video.outputs,
      };

      // Get external URLs
      const externalVideosBaseUrl = config.getExternalVideosBaseUrl();
      const externalResourcesBaseUrl = config.getExternalResourcesBaseUrl();

      // Render the embedded video template using view engine
      const replyWithView = reply as FastifyReplyWithView;

      if (typeof replyWithView.view === 'function') {
        await replyWithView.view('embed-video', {
          video: videoData,
          autostart: autostart === '1' || autostart === 'true',
          externalVideosBaseUrl,
          externalResourcesBaseUrl,
          nodeSettings: {
            nodeName: nodeSettings.nodeName,
            nodeAbout: nodeSettings.nodeAbout,
            nodeId: nodeSettings.nodeId,
            publicNodeProtocol: nodeSettings.publicNodeProtocol,
            publicNodeAddress: nodeSettings.publicNodeAddress,
            publicNodePort: nodeSettings.publicNodePort,
            isCloudflareTurnstileEnabled: nodeSettings.isCloudflareTurnstileEnabled,
            cloudflareTurnstileSiteKey: nodeSettings.cloudflareTurnstileSiteKey,
          },
        });
      } else {
        // Fallback: return JSON data if view engine not registered
        this.sendSuccess(reply, {
          video: videoData,
          autostart: autostart === '1' || autostart === 'true',
          externalVideosBaseUrl,
          externalResourcesBaseUrl,
        });
      }
    } catch (_error) {
      this.sendError(reply, 'error loading embedded video');
    }
  };

  /**
   * GET /watch/embed/chat/:videoId
   *
   * Render embedded chat page
   */
  getEmbedChat = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { videoId } = request.params as VideoIdParams;

      const video = await this.videoRepository.findById(videoId);

      if (!video) {
        this.sendError(reply, 'video not found', 404);
        return;
      }

      const config = getConfig();
      const nodeSettings = config.nodeSettings;

      // Get links and wallet addresses for monetization display
      const links = await this.linkRepository.findAll();
      const cryptoWalletAddresses = await this.monetizationRepository.findAll();

      const externalResourcesBaseUrl = config.getExternalResourcesBaseUrl();

      // Render the embedded chat template using view engine
      const replyWithView = reply as FastifyReplyWithView;

      if (typeof replyWithView.view === 'function') {
        await replyWithView.view('embed-chat', {
          videoId: video.videoId,
          isLiveChatEnabled: video.isLiveChatEnabled,
          isLive: video.isLive,
          isStreaming: video.isStreaming,
          externalResourcesBaseUrl,
          links,
          cryptoWalletAddresses,
          nodeSettings: {
            nodeName: nodeSettings.nodeName,
            nodeAbout: nodeSettings.nodeAbout,
            nodeId: nodeSettings.nodeId,
            publicNodeProtocol: nodeSettings.publicNodeProtocol,
            publicNodeAddress: nodeSettings.publicNodeAddress,
            publicNodePort: nodeSettings.publicNodePort,
            isCloudflareTurnstileEnabled: nodeSettings.isCloudflareTurnstileEnabled,
            cloudflareTurnstileSiteKey: nodeSettings.cloudflareTurnstileSiteKey,
          },
        });
      } else {
        // Fallback: return JSON data if view engine not registered
        this.sendSuccess(reply, {
          videoId: video.videoId,
          isLiveChatEnabled: video.isLiveChatEnabled,
          isLive: video.isLive,
          isStreaming: video.isStreaming,
          externalResourcesBaseUrl,
          links,
          cryptoWalletAddresses,
        });
      }
    } catch (_error) {
      this.sendError(reply, 'error loading embedded chat');
    }
  };
}

/**
 * Watch Controller
 *
 * Handles the main video watch page.
 */
import type { FastifyRequest, FastifyReply } from 'fastify';

import { BaseController } from './base.js';
import type { VideosRepository } from '../database/repositories/videos.js';
import type { CommentsRepository } from '../database/repositories/comments.js';
import type { LinksRepository } from '../database/repositories/links.js';
import type { MonetizationRepository } from '../database/repositories/monetization.js';
import type { DrizzleVideo } from '../database/schema/index.js';
import { getConfig } from '../config/index.js';
import { isVideoIdValid } from '../utils/index.js';

/**
 * Fastify reply with view engine support
 */
interface FastifyReplyWithView extends FastifyReply {
  view?: (template: string, data: Record<string, unknown>) => FastifyReply;
}

/**
 * Query parameters for watch page
 */
export interface WatchQuery {
  v?: string;
}

/**
 * Video source info
 */
interface VideoSource {
  format: string;
  resolution: string;
  url: string;
}

/**
 * Node information data
 */
interface NodeInformationData {
  isError: false;
  information: {
    nodeVideoCount: number;
    nodeId: string;
    nodeName: string;
    nodeAbout: string;
    publicNodeProtocol: string;
    publicNodeAddress: string;
    publicNodePort: string;
    cloudflareTurnstileSiteKey: string;
  };
}

/**
 * Video data for watch page
 */
interface VideoData {
  isError: false;
  video: {
    videoId: string;
    title: string;
    description: string | null;
    tags: string | null;
    views: number;
    likes: number;
    dislikes: number;
    isPublished: boolean;
    isStreaming: boolean;
    isStreamed: boolean;
    isCommentsEnabled: boolean;
    isReportsEnabled: boolean;
    creationTimestamp: number;
    adaptiveSources: VideoSource[];
    progressiveSources: VideoSource[];
  };
}

/**
 * Page data for watch page
 */
interface WatchPageData {
  informationData: NodeInformationData;
  linksData: { isError: false; links: unknown[] };
  cryptoWalletAddressesData: { isError: false; cryptoWalletAddresses: unknown[] };
  videoData: VideoData;
  recommendedVideosData: {
    isError: false;
    recommendedVideos: Array<{
      videoId: string;
      title: string;
      tags: string | null;
      views: number;
      creationTimestamp: number;
    }>;
  };
  commentsData: {
    isError: false;
    comments: Array<{ commentId: number; timestamp: number; commentPlainTextSanitized: string }>;
  };
  externalVideosBaseUrl: string;
  externalResourcesBaseUrl: string;
  adaptiveSources: VideoSource[];
  progressiveSources: VideoSource[];
}

/**
 * WatchController class
 *
 * Handles:
 * - Main video watch page rendering
 */
export class WatchController extends BaseController {
  constructor(
    private readonly videoRepository: VideosRepository,
    private readonly commentRepository: CommentsRepository,
    private readonly linkRepository: LinksRepository,
    private readonly monetizationRepository: MonetizationRepository
  ) {
    super('WatchController');
  }

  /**
   * GET /watch
   *
   * Render the video watch page
   */
  getWatchPage = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    try {
      const { v: videoId } = request.query as WatchQuery;

      if (videoId === undefined || videoId === '' || !isVideoIdValid(videoId, false)) {
        void reply.status(400).send('invalid video id');
        return;
      }

      const config = getConfig();
      const video = await this.videoRepository.findById(videoId);

      if (!video) {
        void reply.status(404).send('that video could not be loaded');
        return;
      }

      const pageData = await this.buildPageData(video, videoId, config);
      this.setCacheHeaders(reply, video, pageData.adaptiveSources, pageData.progressiveSources);
      this.renderPage(reply, pageData);
    } catch (error) {
      this.logger.error('Watch page rendering failed', error instanceof Error ? error : null);
      void reply.status(500).send('that video could not be loaded');
    }
  };

  /**
   * Build all data needed for the watch page
   */
  private async buildPageData(
    video: DrizzleVideo,
    videoId: string,
    config: ReturnType<typeof getConfig>
  ): Promise<WatchPageData> {
    const nodeSettings = config.nodeSettings;
    const externalVideosBaseUrl = config.getExternalVideosBaseUrl();
    const externalResourcesBaseUrl = config.getExternalResourcesBaseUrl();

    // Fetch all data in parallel
    const [videoCount, links, walletAddresses, recommendedVideos, comments] = await Promise.all([
      this.videoRepository.count({ isPublished: true }),
      this.linkRepository.findAll(),
      this.monetizationRepository.findAll(),
      this.videoRepository.findAll({
        isPublished: true,
        limit: 10,
        sortBy: 'creation_timestamp',
        sortDirection: 'desc',
      }),
      this.commentRepository.findByVideoId(videoId, { limit: 50 }),
    ]);

    const { adaptiveSources, progressiveSources } = this.buildVideoSources(
      video,
      externalVideosBaseUrl
    );

    return {
      informationData: this.buildNodeInformation(nodeSettings, videoCount),
      linksData: { isError: false as const, links },
      cryptoWalletAddressesData: {
        isError: false as const,
        cryptoWalletAddresses: walletAddresses,
      },
      videoData: this.buildVideoData(video, adaptiveSources, progressiveSources),
      recommendedVideosData: {
        isError: false as const,
        recommendedVideos: recommendedVideos.map((v) => ({
          videoId: v.videoId,
          title: v.title,
          tags: v.tags,
          views: v.views,
          creationTimestamp: v.creationTimestamp,
        })),
      },
      commentsData: {
        isError: false as const,
        comments: comments.map((c) => ({
          commentId: c.id,
          timestamp: c.timestamp,
          commentPlainTextSanitized: c.commentPlainTextSanitized,
        })),
      },
      externalVideosBaseUrl,
      externalResourcesBaseUrl,
      adaptiveSources,
      progressiveSources,
    };
  }

  /**
   * Build node information data
   */
  private buildNodeInformation(
    nodeSettings: ReturnType<typeof getConfig>['nodeSettings'],
    videoCount: number
  ): NodeInformationData {
    return {
      isError: false as const,
      information: {
        nodeVideoCount: videoCount,
        nodeId: String(nodeSettings.nodeId ?? ''),
        nodeName: String(nodeSettings.nodeName ?? ''),
        nodeAbout: String(nodeSettings.nodeAbout ?? ''),
        publicNodeProtocol: String(nodeSettings.publicNodeProtocol ?? ''),
        publicNodeAddress: String(nodeSettings.publicNodeAddress ?? ''),
        publicNodePort: String(nodeSettings.publicNodePort ?? ''),
        cloudflareTurnstileSiteKey: String(nodeSettings.cloudflareTurnstileSiteKey ?? ''),
      },
    };
  }

  /**
   * Build video sources from metadata
   */
  private buildVideoSources(
    video: DrizzleVideo,
    externalVideosBaseUrl: string
  ): { adaptiveSources: VideoSource[]; progressiveSources: VideoSource[] } {
    const adaptiveSources: VideoSource[] = [];
    const progressiveSources: VideoSource[] = [];

    if (!video.isPublished && !video.isLive) {
      return { adaptiveSources, progressiveSources };
    }

    const formats = this.parseVideoFormats(video);

    if (formats['m3u8'] === true) {
      adaptiveSources.push({
        format: 'hls',
        resolution: 'auto',
        url: `${externalVideosBaseUrl}/${video.videoId}/adaptive/dynamic/manifest-master.m3u8`,
      });
    }

    const resolutions = ['2160p', '1440p', '1080p', '720p', '480p', '360p', '240p'];
    for (const resolution of resolutions) {
      if (formats[`mp4_${resolution}`] === true) {
        progressiveSources.push({
          format: 'mp4',
          resolution,
          url: `${externalVideosBaseUrl}/${video.videoId}/progressive/${resolution}.mp4`,
        });
      }
    }

    return { adaptiveSources, progressiveSources };
  }

  /**
   * Parse video format metadata
   */
  private parseVideoFormats(video: DrizzleVideo): Record<string, unknown> {
    if (video.meta === undefined || video.meta === null || video.meta === '') {
      return {};
    }
    try {
      return JSON.parse(String(video.meta)) as Record<string, unknown>;
    } catch {
      return {};
    }
  }

  /**
   * Build video data response
   */
  private buildVideoData(
    video: DrizzleVideo,
    adaptiveSources: VideoSource[],
    progressiveSources: VideoSource[]
  ): VideoData {
    return {
      isError: false as const,
      video: {
        videoId: video.videoId,
        title: video.title,
        description: video.description,
        tags: video.tags,
        views: video.views,
        likes: video.likes,
        dislikes: video.dislikes,
        isPublished: video.isPublished,
        isStreaming: video.isLive,
        isStreamed: video.isStreamed,
        isCommentsEnabled: video.isCommentsEnabled,
        isReportsEnabled: video.isReportsEnabled,
        creationTimestamp: video.creationTimestamp,
        adaptiveSources,
        progressiveSources,
      },
    };
  }

  /**
   * Set appropriate cache headers
   */
  private setCacheHeaders(
    reply: FastifyReply,
    video: DrizzleVideo,
    adaptiveSources: VideoSource[],
    progressiveSources: VideoSource[]
  ): void {
    const hasSources = adaptiveSources.length > 0 || progressiveSources.length > 0;
    const isAvailable = video.isPublished || video.isLive;

    if (!hasSources || !isAvailable) {
      const cacheValue = video.isStreamed ? 'public, s-maxage=86400' : 'no-store';
      void reply.header('Cache-Control', cacheValue);
    } else {
      void reply.header('Cache-Control', 'public, s-maxage=86400');
    }
  }

  /**
   * Render the watch page or return JSON
   */
  private renderPage(reply: FastifyReply, data: WatchPageData): void {
    const replyWithView = reply as FastifyReplyWithView;

    const viewData = {
      informationData: data.informationData,
      linksData: data.linksData,
      cryptoWalletAddressesData: data.cryptoWalletAddressesData,
      videoData: data.videoData,
      recommendedVideosData: data.recommendedVideosData,
      commentsData: data.commentsData,
      externalVideosBaseUrl: data.externalVideosBaseUrl,
      externalResourcesBaseUrl: data.externalResourcesBaseUrl,
    };

    if (replyWithView.view) {
      void replyWithView.view('watch', viewData);
    } else {
      void reply.send(viewData);
    }
  }
}

/**
 * IPC Channel
 *
 * Abstraction layer for inter-process communication between
 * cluster master and worker processes.
 */

import cluster from 'node:cluster';
import type { Worker } from 'node:cluster';
import type {
  IPCCommand,
  IPCMessage,
  IPCMessageToMaster,
  IPCMessageToWorker,
} from '../../types/ipc.js';

/**
 * IPC message handler function type
 */
export type IPCHandler<T extends IPCMessage = IPCMessage> = (
  message: T,
  worker?: Worker
) => void | Promise<void>;

/**
 * Logger interface for IPC
 */
export interface IPCLogger {
  debug: (message: string, context?: Record<string, unknown>) => void;
  info: (message: string, context?: Record<string, unknown>) => void;
  warn: (message: string, context?: Record<string, unknown>) => void;
  error: (message: string, error?: Error, context?: Record<string, unknown>) => void;
}

/**
 * Default console logger
 */
const defaultLogger: IPCLogger = {
  debug: (message, context) => {
    if (process.env['NODE_ENV'] === 'development') {
      console.debug(`[IPC] ${message}`, context ?? '');
    }
  },
  info: (message, context) => {
    console.info(`[IPC] ${message}`, context ?? '');
  },
  warn: (message, context) => {
    console.warn(`[IPC] ${message}`, context ?? '');
  },
  error: (message, error, context) => {
    console.error(`[IPC] ${message}`, error ?? '', context ?? '');
  },
};

/**
 * IPC Channel for cluster communication
 *
 * Provides a typed interface for sending and receiving
 * messages between master and worker processes.
 */
export class IPCChannel {
  private handlers = new Map<IPCCommand, IPCHandler>();
  private readonly logger: IPCLogger;
  private isListening = false;

  constructor(logger?: IPCLogger) {
    this.logger = logger ?? defaultLogger;
  }

  /**
   * Register a handler for a specific IPC command
   */
  on<T extends IPCMessage>(command: T['cmd'], handler: IPCHandler<T>): void {
    this.handlers.set(command, handler as IPCHandler);
    this.logger.debug(`Registered handler for: ${command}`);
  }

  /**
   * Remove a handler for a command
   */
  off(command: IPCCommand): void {
    this.handlers.delete(command);
  }

  /**
   * Start listening for IPC messages
   * Call this after registering handlers
   */
  startListening(): void {
    if (this.isListening) {
      return;
    }

    if (cluster.isPrimary) {
      this.startMasterListener();
    } else {
      this.startWorkerListener();
    }

    this.isListening = true;
  }

  /**
   * Set up message listener for master process
   */
  private startMasterListener(): void {
    // Listen for messages from each worker
    cluster.on('message', (worker: Worker, message: unknown) => {
      this.handleMessage(message as IPCMessage, worker);
    });

    this.logger.debug('Master IPC listener started');
  }

  /**
   * Set up message listener for worker process
   */
  private startWorkerListener(): void {
    process.on('message', (message: unknown) => {
      this.handleMessage(message as IPCMessage);
    });

    this.logger.debug('Worker IPC listener started');
  }

  /**
   * Handle incoming IPC message
   */
  private handleMessage(message: IPCMessage, worker?: Worker): void {
    if (!message?.cmd) {
      this.logger.warn('Received invalid IPC message', { message });
      return;
    }

    const handler = this.handlers.get(message.cmd);

    if (handler === undefined) {
      this.logger.debug(`No handler for command: ${message.cmd}`);
      return;
    }

    try {
      void Promise.resolve(handler(message, worker)).catch((error: unknown) => {
        this.logger.error(`Handler error for ${message.cmd}`, error as Error);
      });
    } catch (error) {
      this.logger.error(`Sync handler error for ${message.cmd}`, error as Error);
    }
  }

  /**
   * Send a message from worker to master
   * Only call this from worker processes
   */
  sendToMaster(message: IPCMessageToMaster): boolean {
    if (cluster.isPrimary) {
      this.logger.warn('Cannot send to master from master process');
      return false;
    }

    if (process.send === undefined) {
      this.logger.error('process.send is not available');
      return false;
    }

    try {
      process.send(message);
      return true;
    } catch (error) {
      this.logger.error('Failed to send message to master', error as Error);
      return false;
    }
  }

  /**
   * Send a message from master to a specific worker
   * Only call this from master process
   */
  sendToWorker(worker: Worker, message: IPCMessageToWorker): boolean {
    if (!cluster.isPrimary) {
      this.logger.warn('Cannot send to worker from worker process');
      return false;
    }

    if (worker.isDead()) {
      this.logger.warn('Cannot send to dead worker', { workerId: worker.id });
      return false;
    }

    try {
      worker.send(message);
      return true;
    } catch (error) {
      this.logger.error('Failed to send message to worker', error as Error, {
        workerId: worker.id,
      });
      return false;
    }
  }

  /**
   * Broadcast a message from master to all workers
   * Only call this from master process
   */
  broadcast(message: IPCMessageToWorker): void {
    if (!cluster.isPrimary) {
      this.logger.warn('Cannot broadcast from worker process');
      return;
    }

    const workers = cluster.workers;
    if (workers === undefined) {
      return;
    }

    for (const worker of Object.values(workers)) {
      if (worker !== undefined && !worker.isDead()) {
        this.sendToWorker(worker, message);
      }
    }
  }

  /**
   * Get the current worker ID (only valid in worker process)
   */
  getWorkerId(): number | undefined {
    return cluster.worker?.id;
  }

  /**
   * Check if this is the master process
   */
  isMaster(): boolean {
    return cluster.isPrimary;
  }

  /**
   * Check if this is a worker process
   */
  isWorker(): boolean {
    return cluster.isWorker;
  }

  /**
   * Get all active workers (only valid in master process)
   */
  getWorkers(): Worker[] {
    if (!cluster.isPrimary) {
      return [];
    }

    const workers = cluster.workers;
    if (workers === undefined) {
      return [];
    }

    return Object.values(workers).filter((w): w is Worker => w !== undefined && !w.isDead());
  }
}

/**
 * Singleton IPC channel instance
 */
let ipcChannelInstance: IPCChannel | null = null;

/**
 * Get or create the IPC channel instance
 */
export function getIPCChannel(logger?: IPCLogger): IPCChannel {
  if (ipcChannelInstance === null) {
    ipcChannelInstance = new IPCChannel(logger);
  }
  return ipcChannelInstance;
}

/**
 * Reset the IPC channel (for testing)
 */
export function resetIPCChannel(): void {
  ipcChannelInstance = null;
}

/**
 * Cluster Master
 *
 * Master process manager for the MoarTube-Node cluster.
 * Handles worker forking, IPC coordination, and periodic tasks.
 */

import cluster from 'node:cluster';
import os from 'node:os';
import crypto from 'node:crypto';
import { Mutex } from 'async-mutex';
import type {
  DatabaseWriteJobMessage,
  LiveStreamWorkerStatsResponseMessage,
  RestartDatabaseMessage,
  LiveStreamWatchingCountsTracker,
} from '../../types/ipc.js';
import type { WebSocketMessage } from '../../types/websocket.js';
import { IPCChannel, type IPCLogger } from './ipc-channel.js';

/**
 * Database operations interface
 */
export interface MasterDatabaseOperations {
  provision: () => Promise<void>;
  open: () => Promise<void>;
  executeWrite: (query: string, parameters: unknown[]) => Promise<void>;
  readAll: <T>(query: string, parameters: unknown[]) => Promise<T[]>;
}

/**
 * Indexer operations interface
 */
export interface MasterIndexerOperations {
  doIndexUpdate: (data: unknown) => Promise<{ isError: boolean; message?: string }>;
}

/**
 * Cloudflare operations interface
 */
export interface MasterCloudflareOperations {
  purgeAllWatchPages: () => Promise<void>;
  purgeNodePage: () => Promise<void>;
}

/**
 * Node identification interface
 */
export interface NodeIdentification {
  moarTubeTokenProof: string;
}

/**
 * Master configuration
 */
export interface ClusterMasterConfig {
  /** Logger instance */
  logger?: IPCLogger;
  /** Database operations */
  database: MasterDatabaseOperations;
  /** Indexer operations */
  indexer?: MasterIndexerOperations;
  /** Cloudflare operations */
  cloudflare?: MasterCloudflareOperations;
  /** Get node settings */
  getNodeSettings: () => Record<string, unknown>;
  /** Set node settings */
  setNodeSettings: (settings: Record<string, unknown>) => void;
  /** Get node identification */
  getNodeIdentification: () => NodeIdentification;
  /** Perform node identification */
  performNodeIdentification: () => Promise<void>;
  /** Generate video ID */
  generateVideoId: () => Promise<string>;
  /** Get node icon */
  getNodeIconPngBase64: () => string;
  /** Get node avatar */
  getNodeAvatarPngBase64: () => string;
  /** Get video preview */
  getVideoPreviewJpgBase64: (
    nodeSettings: Record<string, unknown>,
    videoId: string
  ) => Promise<string>;
  /** Submit database write job */
  submitDatabaseWriteJob: (query: string, parameters: unknown[]) => Promise<void>;
}

/**
 * Default logger
 */
const defaultLogger: IPCLogger = {
  debug: (message, context) => {
    if (process.env['NODE_ENV'] === 'development') {
      console.debug(`[Master] ${message}`, context ?? '');
    }
  },
  info: (message, context) => {
    console.info(`[Master] ${message}`, context ?? '');
  },
  warn: (message, context) => {
    console.warn(`[Master] ${message}`, context ?? '');
  },
  error: (message, error, context) => {
    console.error(`[Master] ${message}`, error ?? '', context ?? '');
  },
};

/**
 * Cluster Master Process Manager
 *
 * Coordinates the cluster, handles IPC, and runs periodic tasks.
 */
export class ClusterMaster {
  private readonly ipc: IPCChannel;
  private readonly logger: IPCLogger;
  private readonly config: ClusterMasterConfig;
  private readonly mutex = new Mutex();
  private readonly jwtSecret: string;
  private liveStreamWatchingCountsTracker: LiveStreamWatchingCountsTracker = {};
  private intervalHandles: NodeJS.Timeout[] = [];
  private isRunning = false;

  constructor(config: ClusterMasterConfig) {
    this.config = config;
    this.logger = config.logger ?? defaultLogger;
    this.ipc = new IPCChannel(this.logger);
    this.jwtSecret = crypto.randomBytes(32).toString('hex');
  }

  /**
   * Start the cluster master
   */
  async start(): Promise<void> {
    if (this.isRunning) {
      return;
    }

    this.logger.info('Starting MoarTube Node cluster master');

    // Set up global error handlers
    this.setupErrorHandlers();

    // Provision database
    await this.config.database.provision();

    // Ensure node has an ID
    await this.ensureNodeId();

    // Set up IPC handlers
    this.setupIPCHandlers();
    this.ipc.startListening();

    // Fork workers
    this.forkWorkers();

    // Set up worker exit handler
    this.setupWorkerExitHandler();

    // Start periodic tasks
    this.startPeriodicTasks();

    this.isRunning = true;
    this.logger.info('Cluster master started');
  }

  /**
   * Stop the cluster master
   */
  stop(): Promise<void> {
    if (!this.isRunning) {
      return Promise.resolve();
    }

    this.logger.info('Stopping cluster master');

    // Clear intervals
    for (const handle of this.intervalHandles) {
      clearInterval(handle);
    }
    this.intervalHandles = [];

    // Gracefully shut down workers
    for (const worker of this.ipc.getWorkers()) {
      worker.kill('SIGTERM');
    }

    this.isRunning = false;
    return Promise.resolve();
  }

  /**
   * Set up global error handlers
   */
  private setupErrorHandlers(): void {
    process.on('uncaughtException', (error) => {
      this.logger.error('Uncaught exception in master', error);
    });

    process.on('unhandledRejection', (reason) => {
      this.logger.error('Unhandled rejection in master', reason as Error);
    });
  }

  /**
   * Ensure node has an ID
   */
  private async ensureNodeId(): Promise<void> {
    const nodeSettings = this.config.getNodeSettings() as { nodeId?: string };

    if (nodeSettings.nodeId === undefined || nodeSettings.nodeId === '') {
      nodeSettings.nodeId = await this.config.generateVideoId();
      this.config.setNodeSettings(nodeSettings);
      this.logger.info('Generated new node ID');
    }
  }

  /**
   * Set up IPC message handlers
   */
  private setupIPCHandlers(): void {
    // JWT secret request
    this.ipc.on('get_jwt_secret', (_message, worker) => {
      if (worker !== undefined) {
        this.ipc.sendToWorker(worker, {
          cmd: 'get_jwt_secret_response',
          jwtSecret: this.jwtSecret,
        });
      }
    });

    // Node name update
    this.ipc.on('update_node_name', (message) => {
      const nodeName = (message as { nodeName: string }).nodeName;
      this.ipc.broadcast({
        cmd: 'update_node_name_response',
        nodeName,
      });
    });

    // WebSocket broadcast
    this.ipc.on('websocket_broadcast', (message) => {
      const wsMessage = (message as { message: unknown }).message;
      this.ipc.broadcast({
        cmd: 'websocket_broadcast_response',
        message: wsMessage as WebSocketMessage,
      });
    });

    // WebSocket chat broadcast
    this.ipc.on('websocket_broadcast_chat', (message) => {
      const wsMessage = (message as { message: unknown }).message;
      this.ipc.broadcast({
        cmd: 'websocket_broadcast_chat_response',
        message: wsMessage as WebSocketMessage & { videoId: string },
      });
    });

    // Database write job
    this.ipc.on<DatabaseWriteJobMessage>('database_write_job', async (message, worker) => {
      const release = await this.mutex.acquire();

      try {
        await this.config.database.executeWrite(message.query, message.parameters);

        if (worker !== undefined) {
          this.ipc.sendToWorker(worker, {
            cmd: 'database_write_job_result',
            databaseWriteJobId: message.databaseWriteJobId,
          });
        }
      } catch (error) {
        if (worker !== undefined) {
          this.ipc.sendToWorker(worker, {
            cmd: 'database_write_job_result',
            databaseWriteJobId: message.databaseWriteJobId,
            error: error as Error,
          });
        }
      } finally {
        release();
      }
    });

    // Live stream stats response from worker
    this.ipc.on<LiveStreamWorkerStatsResponseMessage>(
      'live_stream_worker_stats_response',
      (message) => {
        this.liveStreamWatchingCountsTracker[message.workerId] = message.liveStreamWatchingCounts;
      }
    );

    // Server restart request
    this.ipc.on('restart_server', () => {
      this.ipc.broadcast({ cmd: 'restart_server_response' });
    });

    // Database restart request
    this.ipc.on<RestartDatabaseMessage>('restart_database', async (message) => {
      this.logger.info(`Changing database configuration to: ${message.databaseDialect}`);
      await this.config.database.open();
      this.ipc.broadcast({ cmd: 'restart_database_response' });
    });
  }

  /**
   * Fork worker processes
   */
  private forkWorkers(): void {
    const numCPUs = os.cpus().length;

    for (let i = 0; i < numCPUs; i++) {
      cluster.fork();
    }

    this.logger.info(`Forked ${numCPUs} workers`);
  }

  /**
   * Set up handler for worker exit
   */
  private setupWorkerExitHandler(): void {
    cluster.on('exit', (worker, code, signal) => {
      this.logger.warn(`Worker ${worker.id} exited`, { code, signal });

      // Clean up tracking - use assignment to undefined to avoid dynamic delete
      // eslint-disable-next-line @typescript-eslint/no-dynamic-delete
      delete this.liveStreamWatchingCountsTracker[worker.id];

      // Fork replacement worker
      if (this.isRunning) {
        cluster.fork();
      }
    });
  }

  /**
   * Start periodic tasks
   */
  private startPeriodicTasks(): void {
    // Index update task (every 3 seconds)
    this.intervalHandles.push(
      setInterval(() => {
        void this.runIndexUpdateTask();
      }, 3000)
    );

    // Cloudflare purge task (every 10 minutes)
    if (this.config.cloudflare !== undefined) {
      this.intervalHandles.push(
        setInterval(() => {
          void this.runCloudflarePurgeTask();
        }, 60000 * 10)
      );
    }

    // Request live stream stats from workers (every second)
    this.intervalHandles.push(
      setInterval(() => {
        this.ipc.broadcast({ cmd: 'live_stream_worker_stats_request' });
      }, 1000)
    );

    // Broadcast aggregated live stream stats (every second)
    this.intervalHandles.push(
      setInterval(() => {
        this.ipc.broadcast({
          cmd: 'live_stream_worker_stats_update',
          liveStreamWatchingCountsTracker: this.liveStreamWatchingCountsTracker,
        });
      }, 1000)
    );
  }

  /**
   * Run index update task
   */
  private async runIndexUpdateTask(): Promise<void> {
    if (this.config.indexer === undefined) {
      return;
    }

    try {
      const videos = await this.config.database.readAll<{
        video_id: string;
        title: string;
        tags: string;
        views: number;
        is_streaming: boolean;
        length_seconds: number;
      }>('SELECT * FROM videos WHERE is_indexed = ? AND is_index_outdated = ?', [true, true]);

      if (videos.length === 0) {
        return;
      }

      await this.config.performNodeIdentification();

      const nodeSettings = this.config.getNodeSettings();
      const nodeIdentification = this.config.getNodeIdentification();

      for (const video of videos) {
        try {
          const videoPreviewJpgBase64 = await this.config.getVideoPreviewJpgBase64(
            nodeSettings,
            video.video_id
          );

          const data = {
            videoId: video.video_id,
            title: video.title,
            tags: video.tags,
            views: video.views,
            isStreaming: Boolean(video.is_streaming),
            lengthSeconds: video.length_seconds,
            nodeIconPngBase64: this.config.getNodeIconPngBase64(),
            nodeAvatarPngBase64: this.config.getNodeAvatarPngBase64(),
            videoPreviewJpgBase64,
            moarTubeTokenProof: nodeIdentification.moarTubeTokenProof,
          };

          const response = await this.config.indexer.doIndexUpdate(data);

          if (response.isError) {
            throw new Error(response.message);
          }

          await this.config.submitDatabaseWriteJob(
            'UPDATE videos SET is_index_outdated = ? WHERE video_id = ?',
            [false, video.video_id]
          );

          this.logger.debug(`Updated video index: ${video.video_id}`);
        } catch (error) {
          this.logger.error(`Failed to update index for video: ${video.video_id}`, error as Error);
        }
      }
    } catch (error) {
      this.logger.error('Index update task failed', error as Error);
    }
  }

  /**
   * Run Cloudflare purge task
   */
  private async runCloudflarePurgeTask(): Promise<void> {
    if (this.config.cloudflare === undefined) {
      return;
    }

    try {
      await this.config.cloudflare.purgeAllWatchPages();
      await this.config.cloudflare.purgeNodePage();
    } catch (error) {
      this.logger.error('Cloudflare purge task failed', error as Error);
    }
  }
}

/**
 * Graceful Shutdown
 *
 * Handles graceful shutdown of the application, ensuring all
 * connections are closed properly and resources are cleaned up.
 */

import type { Server as HttpServer } from 'node:http';
import type { Server as HttpsServer } from 'node:https';
import { createHttpTerminator, type HttpTerminator } from 'http-terminator';
import type { WebSocketManager } from '../websocket/websocket-manager.js';

/**
 * Logger interface for shutdown
 */
export interface ShutdownLogger {
  info: (message: string, context?: Record<string, unknown>) => void;
  warn: (message: string, context?: Record<string, unknown>) => void;
  error: (message: string, error?: Error, context?: Record<string, unknown>) => void;
}

/**
 * Shutdown configuration
 */
export interface GracefulShutdownConfig {
  /** HTTP server to terminate */
  server: HttpServer | HttpsServer;
  /** WebSocket manager for closing connections */
  wsManager?: WebSocketManager;
  /** Cleanup function to run before exit */
  cleanup?: () => Promise<void>;
  /** Logger instance */
  logger?: ShutdownLogger;
  /** Graceful termination timeout in ms */
  terminationTimeout?: number;
}

/**
 * Default console logger
 */
const defaultLogger: ShutdownLogger = {
  info: (message, context) => {
    console.info(`[Shutdown] ${message}`, context ?? '');
  },
  warn: (message, context) => {
    console.warn(`[Shutdown] ${message}`, context ?? '');
  },
  error: (message, error, context) => {
    console.error(`[Shutdown] ${message}`, error ?? '', context ?? '');
  },
};

/**
 * Graceful Shutdown Manager
 *
 * Handles clean shutdown of HTTP server, WebSocket connections,
 * and other resources.
 */
export class GracefulShutdown {
  private isShuttingDown = false;
  private readonly httpTerminator: HttpTerminator;
  private readonly wsManager: WebSocketManager | undefined;
  private readonly cleanup: (() => Promise<void>) | undefined;
  private readonly logger: ShutdownLogger;
  private readonly terminationTimeout: number;

  constructor(config: GracefulShutdownConfig) {
    this.wsManager = config.wsManager;
    this.cleanup = config.cleanup;
    this.logger = config.logger ?? defaultLogger;
    this.terminationTimeout = config.terminationTimeout ?? 10000;

    this.httpTerminator = createHttpTerminator({
      server: config.server,
      gracefulTerminationTimeout: this.terminationTimeout,
    });
  }

  /**
   * Register shutdown handlers for process signals
   */
  register(): void {
    const signals: NodeJS.Signals[] = ['SIGTERM', 'SIGINT'];

    for (const signal of signals) {
      process.on(signal, () => {
        void this.shutdown(signal);
      });
    }

    process.on('uncaughtException', (error) => {
      this.logger.error('Uncaught exception', error);
      void this.shutdown('uncaughtException');
    });

    process.on('unhandledRejection', (reason) => {
      this.logger.error('Unhandled rejection', reason as Error);
      void this.shutdown('unhandledRejection');
    });

    this.logger.info('Shutdown handlers registered');
  }

  /**
   * Perform graceful shutdown
   */
  async shutdown(reason: string): Promise<void> {
    // Prevent multiple shutdown attempts
    if (this.isShuttingDown) {
      return;
    }

    this.isShuttingDown = true;

    this.logger.info(`Shutting down (reason: ${reason})...`);

    try {
      // Step 1: Stop accepting new HTTP connections
      this.logger.info('Terminating HTTP connections...');
      await this.httpTerminator.terminate();

      // Step 2: Close WebSocket connections
      if (this.wsManager !== undefined) {
        this.logger.info('Closing WebSocket connections...');
        this.wsManager.closeAll(1001, 'Server shutting down');
      }

      // Step 3: Run custom cleanup
      if (this.cleanup !== undefined) {
        this.logger.info('Running cleanup tasks...');
        await this.cleanup();
      }

      this.logger.info('Shutdown complete');
      process.exit(0);
    } catch (error) {
      this.logger.error('Error during shutdown', error as Error);
      process.exit(1);
    }
  }

  /**
   * Check if shutdown is in progress
   */
  isInProgress(): boolean {
    return this.isShuttingDown;
  }
}

/**
 * Create a graceful shutdown manager
 */
export function createGracefulShutdown(config: GracefulShutdownConfig): GracefulShutdown {
  return new GracefulShutdown(config);
}

/**
 * Database module barrel export
 *
 * This file exports all database-related modules for convenient importing.
 */

// Connection management
export {
  createDatabase,
  getDatabase,
  isDatabaseInitialized,
  getCurrentDialect,
  closeDatabase,
  getRawSqliteDb,
  getRawPostgresClient,
  isSqliteDb,
  isPostgresDb,
  type DatabaseConfig,
  type DatabaseClient,
} from './connection.js';

// Cluster wrapper
export {
  ClusterDatabaseWrapper,
  getClusterDatabaseWrapper,
  createClusterDatabaseWrapper,
  resetClusterDatabaseWrapper,
} from './cluster-wrapper.js';

// Write queue
export {
  WriteQueue,
  getWriteQueue,
  resetWriteQueue,
  type DatabaseWriteJobMessage,
  type DatabaseWriteJobResultMessage,
} from './write-queue.js';

// Schema exports
export * from './schema/index.js';

// Repository exports
export * from './repositories/index.js';

/**
 * Write Queue for cluster IPC-based database operations
 *
 * In a clustered Node.js application, SQLite requires that all write operations
 * are performed by the master process to avoid database locking issues.
 * This queue handles sending write operations from worker processes to the master.
 */
import { randomUUID } from 'crypto';

/**
 * Pending job interface for tracking submitted write operations
 */
interface PendingJob<T = void> {
  resolve: (value: T) => void;
  reject: (error: Error) => void;
  timestamp: number;
}

/**
 * Database write job message sent via IPC
 */
export interface DatabaseWriteJobMessage {
  cmd: 'database_write_job';
  query: string;
  parameters: unknown[];
  databaseWriteJobId: string;
}

/**
 * Database write job result message received via IPC
 */
export interface DatabaseWriteJobResultMessage {
  cmd: 'database_write_job_result';
  databaseWriteJobId: string;
  error?: string;
  result?: unknown;
}

/**
 * WriteQueue class for managing database write operations in clustered mode
 *
 * Workers submit write operations to this queue, which sends them to the master
 * process via IPC. The master executes the query and sends back the result.
 */
export class WriteQueue {
  private pendingJobs = new Map<string, PendingJob<unknown>>();
  private readonly jobTimeout: number;

  /**
   * Creates a new WriteQueue instance
   *
   * @param jobTimeout - Maximum time in milliseconds to wait for a job to complete (default: 30000)
   */
  constructor(jobTimeout = 30000) {
    this.jobTimeout = jobTimeout;
    this.setupMessageHandler();
    this.startTimeoutChecker();
  }

  /**
   * Submits a database write operation to be executed by the master process
   *
   * @param query - The SQL query string to execute
   * @param parameters - Query parameters
   * @returns Promise that resolves when the write operation completes
   * @throws Error if the operation fails or times out
   */
  submit(query: string, parameters: unknown[] = []): Promise<void> {
    return new Promise((resolve, reject) => {
      const jobId = randomUUID();

      this.pendingJobs.set(jobId, {
        resolve: resolve as (value: unknown) => void,
        reject,
        timestamp: Date.now(),
      });

      const message: DatabaseWriteJobMessage = {
        cmd: 'database_write_job',
        query,
        parameters,
        databaseWriteJobId: jobId,
      };

      // Send to master process
      if (typeof process.send === 'function') {
        process.send(message);
      } else {
        // Not in cluster mode - execute directly would require different handling
        this.pendingJobs.delete(jobId);
        reject(new Error('WriteQueue: Not running in cluster worker mode'));
      }
    });
  }

  /**
   * Submits a database write operation that returns a result
   *
   * @param query - The SQL query string to execute
   * @param parameters - Query parameters
   * @returns Promise that resolves with the query result
   * @throws Error if the operation fails or times out
   */
  submitWithResult<T>(query: string, parameters: unknown[] = []): Promise<T> {
    return new Promise((resolve, reject) => {
      const jobId = randomUUID();

      this.pendingJobs.set(jobId, {
        resolve: resolve as (value: unknown) => void,
        reject,
        timestamp: Date.now(),
      });

      const message: DatabaseWriteJobMessage = {
        cmd: 'database_write_job',
        query,
        parameters,
        databaseWriteJobId: jobId,
      };

      if (typeof process.send === 'function') {
        process.send(message);
      } else {
        this.pendingJobs.delete(jobId);
        reject(new Error('WriteQueue: Not running in cluster worker mode'));
      }
    });
  }

  /**
   * Completes a pending job with optional result or error
   *
   * Called by the message handler when a result is received from the master.
   *
   * @param jobId - The unique job identifier
   * @param error - Optional error if the operation failed
   * @param result - Optional result data from the operation
   */
  complete(jobId: string, error?: Error, result?: unknown): void {
    const job = this.pendingJobs.get(jobId);

    if (job) {
      this.pendingJobs.delete(jobId);

      if (error) {
        job.reject(error);
      } else {
        job.resolve(result);
      }
    }
  }

  /**
   * Gets the number of pending jobs
   *
   * @returns Number of jobs awaiting completion
   */
  getPendingCount(): number {
    return this.pendingJobs.size;
  }

  /**
   * Clears all pending jobs with an error
   *
   * Used during shutdown or when the connection to master is lost.
   *
   * @param error - Error to reject all pending jobs with
   */
  clearAllPending(error: Error): void {
    for (const [jobId, job] of this.pendingJobs) {
      job.reject(error);
      this.pendingJobs.delete(jobId);
    }
  }

  /**
   * Sets up the IPC message handler for receiving results from master
   */
  private setupMessageHandler(): void {
    process.on('message', (message: unknown) => {
      if (
        typeof message === 'object' &&
        message !== null &&
        'cmd' in message &&
        (message as { cmd: string }).cmd === 'database_write_job_result'
      ) {
        const resultMessage = message as DatabaseWriteJobResultMessage;
        const error = resultMessage.error ? new Error(resultMessage.error) : undefined;
        this.complete(resultMessage.databaseWriteJobId, error, resultMessage.result);
      }
    });
  }

  /**
   * Starts a periodic checker to timeout stale jobs
   */
  private startTimeoutChecker(): void {
    setInterval(() => {
      const now = Date.now();

      for (const [jobId, job] of this.pendingJobs) {
        if (now - job.timestamp > this.jobTimeout) {
          this.pendingJobs.delete(jobId);
          job.reject(new Error(`WriteQueue: Job ${jobId} timed out after ${this.jobTimeout}ms`));
        }
      }
    }, 5000); // Check every 5 seconds
  }
}

/**
 * Singleton WriteQueue instance for the application
 */
let writeQueueInstance: WriteQueue | null = null;

/**
 * Gets the singleton WriteQueue instance, creating it if necessary
 *
 * @param jobTimeout - Optional timeout for new instance creation
 * @returns The WriteQueue singleton instance
 */
export function getWriteQueue(jobTimeout?: number): WriteQueue {
  if (!writeQueueInstance) {
    writeQueueInstance = new WriteQueue(jobTimeout);
  }
  return writeQueueInstance;
}

/**
 * Resets the WriteQueue singleton (primarily for testing)
 */
export function resetWriteQueue(): void {
  if (writeQueueInstance) {
    writeQueueInstance.clearAllPending(new Error('WriteQueue reset'));
    writeQueueInstance = null;
  }
}

